CREATE FUNCTION public.provider_opportunity_ids() RETURNS uuid[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=auth.uid() AND m.removed_at IS NULL AND NOT m.is_contractor AND w.account_type='provider' AND w.status='active') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Provider-only operational filter';END IF;RETURN ARRAY(SELECT p.workspace_id FROM public.provider_network_profiles p JOIN public.workspaces w ON w.id=p.workspace_id WHERE p.nearby_opt_in AND p.matching_settings->>'acceptingTrips'='true' AND p.matching_settings->>'availability'='available' AND w.status='active' AND w.provider_verified AND NOT w.is_test_account AND public.provider_network_entitled(w.id));END $$;
REVOKE ALL ON FUNCTION public.provider_opportunity_ids() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.provider_opportunity_ids() TO authenticated;
CREATE FUNCTION public.pilot_offer_state_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text;src uuid;BEGIN IF NEW.status IS DISTINCT FROM OLD.status OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents THEN typ:=CASE NEW.status WHEN 'accepted' THEN 'Offer accepted' WHEN 'declined' THEN 'Offer declined' WHEN 'expired' THEN 'Offer expired' WHEN 'countered' THEN 'Counter received' ELSE 'Offer updated' END;SELECT source_workspace_id INTO src FROM public.trip_distributions WHERE id=NEW.distribution_id;PERFORM public.network_notify(NEW.provider_workspace_id,typ,NEW.id,true);IF src IS NOT NULL THEN PERFORM public.network_notify(src,typ,NEW.id,true);END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER pilot_offer_state_events AFTER UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.pilot_offer_state_notice();